  const A = KEYS[a], B = KEYS[a + 1], w = Math.min(1, Math.max(0, (f - A.frame) / (B.frame - A.frame)));
  const near = w < .5 ? A : B, other = w < .5 ? B : A, wOther = w < .5 ? w : 1 - w;
  gl.useProgram(prog); gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
  const o = f * 12; gl.uniformMatrix3fv(U('Rt'), false, colMajor(POSE.subarray(o, o + 9))); gl.uniform3fv(U('tt'), POSE.subarray(o + 9, o + 12));
